package com.example.birthday.chatservice.config;
import com.example.birthday.chatservice.service.ChatService; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.*; import org.springframework.messaging.simp.config.*; import org.springframework.messaging.simp.stomp.*; import org.springframework.messaging.support.*; import org.springframework.web.socket.config.annotation.*; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.security.Principal; import java.util.UUID;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfig implements WebSocketMessageBrokerConfigurer{
 private final SecretKey key;private final ObjectProvider<ChatService> chats;public WebSocketConfig(@Value("${security.jwt-secret}")String s,ObjectProvider<ChatService> c){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));chats=c;}
 public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws/chats").setAllowedOriginPatterns("*");}
 public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/topic");r.setApplicationDestinationPrefixes("/app");}
 public void configureClientInboundChannel(ChannelRegistration r){r.interceptors(new ChannelInterceptor(){public Message<?> preSend(Message<?> m,MessageChannel c){var a=MessageHeaderAccessor.getAccessor(m,StompHeaderAccessor.class);if(a==null)return m;if(StompCommand.CONNECT.equals(a.getCommand())){String h=a.getFirstNativeHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new MessagingException("WebSocket JWT is required");var claims=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();Principal p=()->claims.getSubject();a.setUser(p);}else if(StompCommand.SUBSCRIBE.equals(a.getCommand())&&a.getDestination()!=null&&a.getDestination().startsWith("/topic/chats/")){if(a.getUser()==null)throw new MessagingException("Authentication required");UUID room=UUID.fromString(a.getDestination().substring("/topic/chats/".length()));chats.getObject().assertAccess(UUID.fromString(a.getUser().getName()),room);}return m;}});}
}
